'use strict';

// MODULES //

var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );


// MAIN //

/**
* Computes the mode of a one-dimensional double-precision floating-point ndarray.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing an input ndarray
* @returns {number} mode value
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
*
* var xbuf = new Float64Array( [ 1.0, 2.0, 2.0, 3.0 ] );
* var x = new ndarray( 'float64', xbuf, [ 4 ], [ 1 ], 0, 'row-major' );
*
* var v = mode( [ x ] );
* // returns 2.0
*/
function mode( arrays ) {
	var modeVal; // 7
	var maxFreq; // 7
	var offset;  // 6
	var stride;  // 6
	var data;    // 4
	var freq;    // 4
	var x;       // 1
	var N;       // 1
	var v;       // 1
	var i;       // 1

	x = arrays[ 0 ];
	N = numelDimension( x, 0 );

	// Edge case: empty ndarray
	if ( N === 0 ) {
		return NaN;
	}

	data = getData( x );
	stride = getStride( x, 0 );
	offset = getOffset( x );

	freq = {};
	maxFreq = 0;
	modeVal = void 0;

	for ( i = 0; i < N; i++ ) {
		// eslint-disable-next-line no-mixed-operators
		v = data[ offset + i*stride ];

		if ( isnan( v ) ) {
			return NaN;
		}

		freq[ v ] = ( freq[ v ] || 0 ) + 1;

		// Highest frequency wins; if tied, choose the smaller value consistently
		if ( freq[ v ] > maxFreq || ( freq[ v ] === maxFreq && ( modeVal === void 0 || v < modeVal ) ) ) {
			maxFreq = freq[ v ];
			modeVal = v;
		}
	}

	return modeVal;
}


// EXPORTS //

module.exports = mode;
